#!/usr/bin/env bash
# Invoke the project-versioned Hermes source with dedicated local state.
# The gateway is trusted; enabled generated-code tools use the Seatbelt provider.
set -euo pipefail
umask 077

project_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
lab_dir="$project_dir/.local/hermes-lab"
source_dir="$project_dir/hermes"

if [[ ! -x "$lab_dir/venv/bin/hermes" ]]; then
  echo "Install the pinned baseline first; see docs/INSTALL.md." >&2
  exit 1
fi
if [[ ! -f "$source_dir/pyproject.toml" ]]; then
  echo "Hermes source is missing; expected hermes/ at the project root." >&2
  exit 1
fi
if [[ -e "$source_dir/.env" ]]; then
  echo "The Hermes source has a fallback .env; keep credentials only in the lab home." >&2
  exit 1
fi

mkdir -p "$lab_dir/home" "$lab_dir/workspace" "$lab_dir/gateway-locks" "$lab_dir/managed"
if [[ ! -f "$lab_dir/home/config.yaml" ]]; then
  cp "$project_dir/config/hermes-defaults.yaml" "$lab_dir/home/config.yaml"
fi
if [[ ! -f "$lab_dir/home/.env" ]]; then
  touch "$lab_dir/home/.env"
fi
chmod 600 "$lab_dir/home/.env"
if [[ -f "$lab_dir/home/.clanker-execution/fleet.json" ]]; then
  if ! env -i HOME="$HOME" PATH="/usr/bin:/bin" \
      "$lab_dir/venv/bin/python" "$project_dir/runtime/seatbelt/recover.py" "$lab_dir/home"; then
    echo "Browser execution is unavailable; continuing with Slack chat." >&2
  fi
fi

cd "$lab_dir/workspace"
# Credentials must be deliberately configured in the lab home. Keep HOME
# unchanged for platform compatibility; do not inherit provider/session vars.
# Command smoke: skip startup model/tool warmup until inference is configured.
exec env -i \
  HOME="$HOME" \
  PATH="$lab_dir/venv/bin:$lab_dir/home/node/bin:$lab_dir/home/bin:/usr/bin:/bin:/usr/sbin:/sbin" \
  TERM="${TERM:-xterm-256color}" \
  LANG="${LANG:-en_US.UTF-8}" \
  HERMES_HOME="$lab_dir/home" \
  PYTHONPATH="$project_dir/runtime" \
  HERMES_MANAGED_DIR="$lab_dir/managed" \
  HERMES_GATEWAY_LOCK_DIR="$lab_dir/gateway-locks" \
  HERMES_DISABLE_LAZY_INSTALLS=1 \
  HERMES_STARTUP_WARMUP_TIMEOUT=0 \
  "$lab_dir/venv/bin/hermes" "$@"
"""Loopback-only invitation preview with disposable vaults and dummy credentials."""
import asyncio
from pathlib import Path
import socket
import sys
import tempfile
from types import SimpleNamespace

from aiohttp import web

ROOT = Path(__file__).resolve().parents[2]
sys.path[:0] = [str(ROOT/'runtime'), str(ROOT/'hermes')]
from agent.vault_store import VaultStore
from vault.service import VaultService
from vault.web import VaultWeb


async def main():
    with tempfile.TemporaryDirectory(prefix='clanker-invitation-ui-') as directory:
        home = Path(directory)
        names = {'OWNER':'yyovil (demo)', 'GUEST':'Tanishq Palandurkar (demo)', 'THIRD':'Another member (demo)'}
        for uid in names:
            (home/'profiles'/uid).mkdir(parents=True)
        listener = socket.socket()
        listener.bind(('127.0.0.1',0))
        port = listener.getsockname()[1]
        listener.close()
        origin = 'http://127.0.0.1:'+str(port)
        policy = SimpleNamespace(home=home,team='TFIXTURE',adapter=SimpleNamespace(),client=lambda:SimpleNamespace(),
            state={'members':{uid:{'name':name,'profile':uid,'status':'ready','dm_id':'D'+uid} for uid,name in names.items()},
                   'conversations':{'D'+uid:{'kind':'dm'} for uid in names}},
            authorize_source=lambda s:s.scope_id=='TFIXTURE' and s.profile==s.user_id and s.chat_id=='D'+s.user_id)
        service = VaultService(policy,{'public_url':origin,'client_id':'fixture','port':port,'local_test':True})
        vault = VaultStore(service.private_home('TFIXTURE','OWNER')/'vault')
        vault.add_item('login','Google account',{'identifier':'demo@example.invalid','identifier_type':'email','password':'REDACTED'},origin='https://accounts.google.com')
        vault.add_item('api_key','Demo service API key',{'api_key':'REDACTED'},origin='https://api.example.invalid')
        vault.add_item('payment','Demo merchant card',{'card_number':'4242424242424242','exp_month':'12','exp_year':'2030'},origin='https://checkout.example.invalid')
        app = VaultWeb(service,service.config)
        async def entry(request):
            uid = request.match_info['identity'].upper()
            if uid not in names:
                raise web.HTTPNotFound()
            response = web.Response(status=302,headers={'Location':'/vault'})
            response.set_cookie('__Host-clanker',service.store.new_session('TFIXTURE',uid),secure=True,httponly=True,samesite='Lax',path='/')
            return response
        app.app.router.add_get('/fixture/{identity}',entry)
        await app.start()
        print('INVITATION_UI_READY '+origin+'/fixture/owner',flush=True)
        try:
            await asyncio.Event().wait()
        finally:
            await app.close()


if __name__=='__main__':
    asyncio.run(main())
    title.textContent=item.label;
    const kind=item.kind==='api_key'?'API key':item.kind==='payment'?'Payment card':'Login';
    detail.textContent=[kind,item.origin,item.identifier].filter(Boolean).join(' · ');
    text.append(title,detail);label.append(input,text);el('credential-selection').append(label);
  }
  if(!invitationState.credentials.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='Save a credential in your vault before inviting someone.';el('credential-selection').append(empty);}
  updateInviteSelection();
}
async function removeMemberAccess(recipient,name){
  if(!confirm('Remove '+name+'’s access to your vault? Any affected private browser sessions will be closed.'))return;
  try{const result=await api('/api/invite',{recipient,handles:[]});await refreshInvitations();
    el('vault-message').textContent=result.cleanup_pending?'Access removed. Browser cleanup is pending; further browser tasks for this member are blocked.':'Access removed.';el('vault-message').hidden=false;
  }catch(error){fail(error);}
}
async function refreshInvitations(){
  const result=await api('/api/invitations',{handle:null});csrf=result.csrf;invitationState=result;
  const selectedMember=el('invite-member').value;
  el('invite-member').replaceChildren(new Option('Choose a member',''));
  const names=new Map(result.members.map(member=>[member.id,member.name]));
  for(const member of result.members){
    const duplicate=result.members.filter(other=>other.name===member.name).length>1;
    const option=new Option(member.name+(duplicate?' · '+member.id.slice(-6):''),member.id);
    el('invite-member').append(option);
  }
  el('invite-member').value=selectedMember;
  el('invite-vault').disabled=!result.credentials.length||!result.members.length;
  renderCredentialSelection();
  renderInvitationList();
  renderDashboard();
}
function renderInvitationList(){
  const result=invitationState;
  const names=new Map(result.members.map(member=>[member.id,member.name]));
  el('invitation-list').replaceChildren();
  if(!result.invitations.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No one else has access to your vault.';el('invitation-list').append(empty);}
  const groups=new Map();
  for(const invitation of result.invitations){if(!groups.has(invitation.recipient))groups.set(invitation.recipient,[]);groups.get(invitation.recipient).push(invitation);}
  for(const [recipient,invitations] of groups){
    const row=document.createElement('div');row.className='invitation-row';
    const name=names.get(recipient)||'Slack member '+recipient;
    const active=invitations.filter(invitation=>invitation.revoked==null),pending=invitations.find(invitation=>invitation.cleanup_pending);
    if(!active.length&&!pending)continue;
    const label=document.createElement('span'),title=document.createElement('strong'),detail=document.createElement('small');
    title.textContent=name;detail.textContent=active.length?active.length+' '+(active.length===1?'credential':'credentials')+' · '+active.map(invitation=>invitation.credential).join(', '):'Access removed';
    label.append(title,detail);
    if(pending){const warning=document.createElement('small');warning.textContent='Browser cleanup pending';label.append(warning);}
    const actions=document.createElement('div');actions.className='sharing-actions';
    if(active.length&&names.has(recipient)){const edit=document.createElement('button');edit.type='button';edit.textContent='Edit access';edit.onclick=()=>openInvitations(recipient);actions.append(edit);}
