    checks.push('real edit-access persistence and recipient revocation after reload');
    await owner.locator('#tab-owned').click();
    await owner.setViewportSize({width:390,height:844});
    await screenshot(owner,'home-mobile');
    await noOverflow(owner);
    await owner.setViewportSize({width:320,height:740});
    await noOverflow(owner);
    checks.push('390px and 320px mobile layouts without horizontal overflow');
    await owner.getByRole('button',{name:'Details for Demo service API key',exact:true}).click();
    owner.once('dialog',dialog=>dialog.accept());
    await owner.getByRole('button',{name:'Disconnect',exact:true}).click();
    await owner.locator('#credential-dialog').waitFor({state:'hidden'});
    await count(owner,2);
    await owner.reload();
    await count(owner,2);
    assert.equal(await owner.locator('#count-owned').innerText(),'2');
    assert.equal(await owner.getByRole('button',{name:'Details for Demo service API key',exact:true}).count(),0);
    checks.push('real disconnect persistence and count update after reload');
    // Exercise existing personal-info editing within the new dashboard shell.
    await owner.locator('#personal-add summary').click();
    await owner.getByRole('button',{name:'Add email',exact:true}).click();
    await owner.locator('#personal-email').fill('primary@example.invalid');
    await owner.getByRole('button',{name:'Save',exact:true}).click();
    await owner.locator('#personal-dialog').waitFor({state:'hidden'});
    await owner.reload();
    await owner.getByRole('button',{name:'Edit primary email',exact:true}).click();
    await owner.waitForFunction(()=>document.querySelector('#personal-email').value==='primary@example.invalid');
    await owner.getByRole('button',{name:'Cancel',exact:true}).click();
    await owner.waitForFunction(()=>document.querySelector('#personal-email').value==='');
    assert.equal(await owner.locator('#personal-email').inputValue(),'');
    await owner.locator('#tab-shared').click();
    assert.equal(await owner.locator('#personal-info').isVisible(),false);
    checks.push('personal-info save/edit persistence, form clearing and private-tab placement');
    for(const page of [owner,guest]) {
      const body=await page.locator('body').innerText();
      assert.equal(body.includes('UI_ONLY_DUMMY'),false);
      assert.equal(body.includes('4242424242424242'),false);
    }
    assert.deepEqual(errors,[]);
    const result={success:true,checks,screenshots:output,browser_errors:errors};
    await fs.writeFile('verification/evidence/2026-10-07-vault-dashboard.json',JSON.stringify(result,null,2)+'\n');
    process.stdout.write(JSON.stringify(result,null,2)+'\n');
  } finally {await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});

